import React, { useState } from 'react';
import axios from 'axios';
import { FaGithub, FaTelegramPlane, FaEnvelope, FaPhoneAlt } from 'react-icons/fa';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const contactLinks = [
  { icon: <FaEnvelope />, label: 'bisratamare88@gmail.com', href: 'mailto:bisratamare88@gmail.com' },
  { icon: <FaPhoneAlt />, label: '+251 923 118 002', href: 'tel:+251923118002' },
  { icon: <FaTelegramPlane />, label: 't.me/BisratLe12', href: 'https://t.me/BisratLe12' },
  { icon: <FaGithub />, label: 'github.com/Bisrat12Amare', href: 'https://github.com/Bisrat12Amare' },
];

export default function Contact() {
  const [form, setForm] = useState({ name: '', email: '', subject: '', message: '' });
  const [status, setStatus] = useState('idle'); // idle | loading | success | error

  const handleChange = e => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async () => {
    if (!form.name || !form.email || !form.message) return;
    setStatus('loading');
    try {
      await axios.post(`${API_URL}/api/contact`, form);
      setStatus('success');
      setForm({ name: '', email: '', subject: '', message: '' });
      setTimeout(() => setStatus('idle'), 5000);
    } catch {
      setStatus('error');
      setTimeout(() => setStatus('idle'), 4000);
    }
  };

  const inputStyle = {
    width: '100%', background: 'var(--surface)',
    border: '1px solid rgba(255,255,255,0.1)',
    borderRadius: 6, padding: '12px 14px',
    color: 'var(--text)', fontFamily: "'Syne', sans-serif",
    fontSize: '0.9rem', outline: 'none',
    transition: 'border-color 0.2s'
  };

  return (
    <section id="contact">
      <div className="section-inner">
        <div className="section-label">{'// 05 — contact'}</div>
        <h2 className="section-title">Let's <span>Connect</span></h2>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4rem' }}>
          {/* Left */}
          <div>
            <h3 style={{ fontSize: '1.2rem', fontWeight: 700, marginBottom: '1rem' }}>Open to opportunities</h3>
            <p style={{ color: 'var(--muted)', fontSize: '0.9rem', lineHeight: 1.8, marginBottom: '2rem' }}>
              I'm available for remote freelance projects, contract roles, and full-time engineering positions.
              Let's build something great together.
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {contactLinks.map(link => (
                <a
                  key={link.label}
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="contact-link"
                >
                  <div className="icon-circle">{link.icon}</div>
                  {link.label}
                </a>
              ))}
            </div>
          </div>

          {/* Right — Form */}
          <div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1.25rem' }}>
              {['name', 'email'].map(field => (
                <div key={field}>
                  <label style={{ display: 'block', fontSize: '0.75rem', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--muted)', marginBottom: '0.5rem' }}>
                    {field === 'name' ? 'Full Name' : 'Email'}
                  </label>
                  <input
                    type={field === 'email' ? 'email' : 'text'}
                    name={field}
                    value={form[field]}
                    onChange={handleChange}
                    placeholder={field === 'name' ? 'John Doe' : 'john@example.com'}
                    style={inputStyle}
                    onFocus={e => e.target.style.borderColor = 'var(--orange)'}
                    onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'}
                  />
                </div>
              ))}
            </div>

            <div style={{ marginBottom: '1.25rem' }}>
              <label style={{ display: 'block', fontSize: '0.75rem', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--muted)', marginBottom: '0.5rem' }}>Subject</label>
              <input
                type="text" name="subject" value={form.subject} onChange={handleChange}
                placeholder="Project Inquiry" style={inputStyle}
                onFocus={e => e.target.style.borderColor = 'var(--orange)'}
                onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'}
              />
            </div>

            <div style={{ marginBottom: '1.5rem' }}>
              <label style={{ display: 'block', fontSize: '0.75rem', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--muted)', marginBottom: '0.5rem' }}>Message</label>
              <textarea
                name="message" value={form.message} onChange={handleChange}
                placeholder="Tell me about your project..."
                style={{ ...inputStyle, minHeight: 120, resize: 'vertical' }}
                onFocus={e => e.target.style.borderColor = 'var(--orange)'}
                onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'}
              />
            </div>

            <button
              onClick={handleSubmit}
              disabled={status === 'loading'}
              className="btn-primary"
              style={{
                width: '100%', justifyContent: 'center',
                background: status === 'success' ? '#2a7a2a' : status === 'error' ? '#7a2a2a' : 'var(--orange)',
                opacity: status === 'loading' ? 0.7 : 1
              }}>
              {status === 'idle' && 'Send Message →'}
              {status === 'loading' && 'Sending...'}
              {status === 'success' && '✓ Message Sent!'}
              {status === 'error' && '✗ Error — Try Again'}
            </button>
          </div>
        </div>
      </div>
    </section>
  );
}
